+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import {ToolRegistry} from './tools/registry.js';
+import {recordingSessionStore, writeSignalPromptBuilder} from '../infrastructure/writeSignalTestSupport.js';
+import type {AIProvider} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+
+describe('a beforeSession hook that throws', () => {
+  it('runs onError then afterSession, skips the turn, and rethrows on a beforeSession throw', async () => {
+    let providerCalls = 0;
+    const provider: AIProvider = {
+      async *sendMessage() {
+        providerCalls += 1;
+        yield {type: 'stop', stopReason: 'end_turn'};
+      },
+      async generateStructured<T>(): Promise<T> {
+        return {} as T;
+      },
+    };
+
+    let toolCalls = 0;
+    const registry = new ToolRegistry();
+    registry.register({name: 'lookup', description: 'Lookup.', inputSchema: {type: 'object'}}, async () => {
+      toolCalls += 1;
+      return 'ok';
+    });
+
+    const failure = new Error('span allocation failed');
+    const seen: string[] = [];
+    const received: Array<{hook: string; session: ChatSession; error?: Error}> = [];
+    const hooks: OrchestratorHooks = {
+      beforeSession: async () => {
+        seen.push('beforeSession');
+        throw failure;
+      },
+      beforeUserInput: async (_session, message) => {
+        seen.push('beforeUserInput');
+        return message;
+      },
+      afterUserInput: async () => void seen.push('afterUserInput'),
+      beforeModelResponse: async (_session, prompt) => {
+        seen.push('beforeModelResponse');
+        return prompt;
+      },
+      afterModelResponse: async () => void seen.push('afterModelResponse'),
+      onError: async (hookSession, error) => {
+        seen.push('onError');
+        received.push({hook: 'onError', session: hookSession, error});
+      },
+      afterSession: async hookSession => {
+        seen.push('afterSession');
+        received.push({hook: 'afterSession', session: hookSession});
+      },
+    };
+
+    const sessionStore = recordingSessionStore(() => void seen.push('save'));
+    const session: ChatSession = {
+      sessionId: 's1',
+      userId: 'u1',
+      entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
+    };
+    const orchestrator = createChatOrchestrator(provider, writeSignalPromptBuilder, registry, {hooks, sessionStore});
+    const thrown = await orchestrator.processMessage(session).catch((caught: unknown) => caught);
+    const {entries} = session;
+
+    expect({
+      thrown,
+      seen,
+      received,
+      providerCalls,
+      toolCalls,
+      roles: entries.map(entry => entry.role),
+    }).toEqual({
+      thrown: failure,
+      seen: ['beforeSession', 'onError', 'afterSession', 'save'],
+      received: [
+        {hook: 'onError', session, error: failure},
+        {hook: 'afterSession', session},
+      ],
+      providerCalls: 0,
+      toolCalls: 0,
+      roles: ['user'],
+    });
+  });
+});
